[Better Approach] Optimized Index-Tracking - O(n) Time and O(n) SpaceWe first store the positions of all '[' in a vector. While scanning the string, we keep a balance counter that goes up for '[' and down for ']'. If the balance becomes negative, it means there are too many ']'. To fix it, we take the next '[' from our vector, swap it forward, and add the swap distance to the answer.
            C++

    #include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int swapCount(string &s){

    // Keep track of '['
    vector<int> pos;
    for (int i = 0; i < s.length(); ++i)
        if (s[i] == '[')
            pos.push_back(i);

     // To count number of encountered '['
    int count = 0; 

    // To track position of next '[' in pos
    int p = 0;  

    // To store result
    int  sum = 0; 
    for (int i = 0; i < s.length(); ++i){

        // Increment count and move p to next position
        if (s[i] == '[')
        {
            count++;
            p++;
        }
        else if (s[i] == ']')
            count--;

        // We have encountered an unbalanced part of string
        if (count < 0){

            // Increment sum by number of swaps required
            // i.e. position of next '[' - current position
            sum += pos[p] - i;
            swap(s[i], s[pos[p]]);
            ++p;

            // Reset count to 1
            count = 1;
        }
    }
    return sum;
}

int main()
{
    string s = "[]][][";
    cout << swapCount(s) << "\n";
    return 0;
}


